# -*- coding: utf-8 -*-
import pathlib
def w(path, lines):
    p = pathlib.Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print('OK:', path)
w('docs/ai/START_HERE.md', ['# START_HERE.md - Guide de demarrage rapide','','## Ordre de lecture au debut de chaque session','','1. AGENTS.md - regles canoniques','2. STATUS.md - etat actuel','3. NEXT_SESSION.md - prochaine action','4. docs/roadmap/sprints/SPRINT-XX.md - sprint actif','5. docs/features/<domaine>/README.md si pertinent','','## Commandes de base (apres bootstrap Next.js)','','  pnpm dev','  pnpm build','  pnpm lint','  pnpm typecheck','  pnpm test','  pnpm test:e2e','  supabase start','  supabase db test','','## Regles importantes','','- Ne pas lire tout le depot a chaque session','- Verifier tests + typecheck + lint avant commit','- Mettre a jour STATUS.md et NEXT_SESSION.md en fin de session','- Voir docs/ai/prompts/ pour les prompts de session'])
w('docs/ai/SESSION_MEMORY_RULES.md', ['# SESSION_MEMORY_RULES.md','','## La source de verite est le depot, pas la conversation','','Une conversation ou le contexte interne ne sont jamais superieurs au depot.','','## Fichiers a mettre a jour a chaque session','','- STATUS.md : etat reel, sprint, bloquants','- NEXT_SESSION.md : prochaine action concrete','- docs/roadmap/sprints/SPRINT-XX.md : statut livrables','- docs/features/<domaine>/README.md : si feature avance','- docs/architecture/adr/XXXX.md : si decision prise','','## Regles','','- Ne pas dupliquer le cahier des charges dans STATUS.md','- Ne pas coller de logs massifs','- Jamais de secrets ni donnees personnelles','- Statuts : fait | partiel | non commence | bloque | non verifie'])
w('docs/ai/prompts/START_SESSION.md', ['# START_SESSION.md','','## Contexte minimal pour demarrer','','Lire dans cet ordre :','1. AGENTS.md','2. STATUS.md','3. NEXT_SESSION.md','4. docs/roadmap/sprints/<sprint_actif>.md','','## Actions initiales','','- Identifier le sprint actif dans STATUS.md','- Lire la feature doc concernee','- Verifier les tests : pnpm test','- Verifier TypeScript : pnpm typecheck','','## Ne pas','','- Lire tout le depot','- Refaire des fichiers deja crees','- Changer de stack sans justification ADR'])
w('docs/ai/prompts/END_SESSION.md', ['# END_SESSION.md','','## Actions de cloture obligatoires','','1. Mettre a jour STATUS.md (etat reel, pas optimiste)','2. Mettre a jour NEXT_SESSION.md (une action principale)','3. Mettre a jour le fichier sprint actif (statut livrables)','4. Mettre a jour la feature doc si avancement','5. Creer/mettre a jour un ADR si decision prise','6. Ajouter une entree CHANGELOG.md si livraison','','## Format du compte rendu','','- Livre et verifie : lister avec preuves (tests passes, build OK)','- Partiel : lister ce qui reste','- Bloque : expliquer pourquoi et la prochaine action','','## Jamais','','- Dire tout est termine sans preuve','- Laisser STATUS.md non mis a jour','- Committer des secrets ou donnees personnelles'])
w('docs/ai/prompts/RESUME_PROJECT.md', ['# RESUME_PROJECT.md','','## Pour reprendre apres un changement d agent ou de conversation','','1. Lire AGENTS.md - regles et commandes','2. Lire STATUS.md - ou en est le projet','3. Lire NEXT_SESSION.md - que faire maintenant','4. Lire docs/roadmap/sprints/<sprint>.md - details du sprint','5. Inspecter le code concerne : git diff HEAD~1, git log --oneline -5','','## Ne pas','','- Reconstruire ce qui existe deja','- Se fier a la memoire conversationnelle','- Changer l architecture sans lire les ADR','','## Verification rapide','','  pnpm typecheck','  pnpm lint','  pnpm test'])
w('docs/ai/prompts/EXECUTE_SPRINT.md', ['# EXECUTE_SPRINT.md','','## Pour executer un sprint complet','','1. Lire docs/roadmap/sprints/SPRINT-XX.md','2. Verifier les dependances (sprints precedents termines)','3. Lire les feature docs concernees','4. Etablir les criteres d acceptation testables','5. Impl�menter par tranches verticales (pas tout d un coup)','6. Tester a chaque livrable','7. Mettre a jour le sprint doc au fur et a mesure','','## Definition du termine','','Voir AGENTS.md section DoD. Un sprint ne se ferme pas sans :','- Tests passes (unit, integration, RLS)','- TypeScript zero erreur','- FR/EN complet','- Accessibilite verifiee','- STATUS.md mis a jour','','## Ordre des livrables','','Base de donnees (migration + RLS + tests) avant UI.','UI avec etats loading/error/empty/success.','Actions serveur avec validation complete avant Client Components.'])
w('docs/ai/prompts/IMPLEMENT_FEATURE.md', ['# IMPLEMENT_FEATURE.md','','## Pour implementer une feature verticalement','','1. Lire docs/features/<slug>/README.md','2. Verifier les ADR pertinents','3. Schema SQL + migration + RLS + tests d acces','4. Types TypeScript generes ou definis','5. Service/queries (pas de logique metier dans les composants)','6. Schemas Zod pour validation','7. Actions serveur (auth + tenant + permission + etat)','8. UI Server Component','9. Client Component uniquement si interaction requise','10. Tests (unit + integration + E2E du parcours)','','## Checklist securite','','- Validation cote serveur (pas seulement client)','- Verification tenant avant toute mutation','- Jamais de secret dans les logs ou reponses API','- RLS testee par tenant (autorise ET refuse)'])
w('docs/ai/prompts/DATABASE_CHANGE.md', ['# DATABASE_CHANGE.md','','## Pour toute modification de base de donnees','','1. Creer la migration dans supabase/migrations/','   Nom : YYYYMMDDHHMMSS_description_au_passe.sql','2. Inclure la migration inverse si possible','3. Ajouter les politiques RLS (une policy par operation)','4. Definir les grants/revokes explicitement','5. Creer des tests dans supabase/tests/','6. Regenerer les types TypeScript','','## Tests obligatoires','','Pour chaque table :','- SELECT autorise (bon tenant, bon role)','- SELECT refuse (mauvais tenant, anon)','- INSERT autorise','- INSERT refuse (mauvais tenant)','- UPDATE autorise','- UPDATE refuse','- DELETE selon politique','','## Commandes','','  supabase db diff','  supabase migration new <nom>','  supabase db reset','  supabase db test','  supabase gen types typescript --local > src/types/database.ts','','## Regles absolues','','- Jamais de modification manuelle en base partagee','- RLS activee sur toute table exposee','- SERVICE_ROLE_KEY jamais cote client'])
w('docs/ai/prompts/SECURITY_REVIEW.md', ['# SECURITY_REVIEW.md','','## Checklist de revue securite','','### Authentification et sessions','- [ ] Endpoints sensibles verifient le niveau d assurance MFA','- [ ] Cookies : HttpOnly, Secure, SameSite','- [ ] Rate limiting sur les endpoints de connexion','- [ ] Tokens d invitation : usage unique, expiration','','### Multi-tenant','- [ ] Chaque mutation verifie le tenant cote serveur','- [ ] Aucun tenant_id du navigateur cru directement','- [ ] RLS testee : refuse inter-tenant','- [ ] Pas d IDOR sur les ressources','','### Vote (gate S22)','- [ ] Aucun lien direct identite-bulletin','- [ ] Journaux sans choix de vote','- [ ] Mode sandbox clairement marque NON_PRODUCTION','','### Secrets','- [ ] Aucun secret dans le bundle client','- [ ] Aucun secret dans les logs','- [ ] SERVICE_ROLE_KEY cote serveur uniquement','','### Dependances','- [ ] pnpm audit sans vulnerabilite critique','- [ ] Versions lockees (pnpm-lock.yaml)'])
w('docs/ai/prompts/CODE_REVIEW.md', ['# CODE_REVIEW.md','','## Checklist de revue de code','','### Correctness','- [ ] La logique metier est dans les services, pas dans les composants','- [ ] Les mutations passent par les actions serveur (auth + tenant + perm)','- [ ] Les schemas Zod valident les entrees','- [ ] Les etats loading/error/empty/success sont tous traites','','### TypeScript','- [ ] Pas de any non justifie','- [ ] Pas de @ts-ignore sans explication et issue','- [ ] Types generes depuis le schema Supabase utilises','','### Securite','- [ ] Pas de secret dans le code ou les logs','- [ ] RLS verifiee pour les nouvelles tables','- [ ] Pas d acces direct a SERVICE_ROLE_KEY cote client','','### Qualite','- [ ] Tests unitaires pour la logique metier','- [ ] Tests RLS (autorise et refuse)','- [ ] FR/EN complet, pas de texte systeme en dur','- [ ] Accessibilite : labels, focus, contraste','','### Git','- [ ] Conventional Commits','- [ ] Pas de mention d outil IA dans les commits'])
w('docs/ai/prompts/DEBUG_AND_FIX.md', ['# DEBUG_AND_FIX.md','','## Pour diagnostiquer et corriger un bug','','1. Reproduire le bug de facon deterministe','2. Identifier la couche concernee (UI, action, service, DB)','3. Lire le code concerne AVANT de le modifier','4. Formuler une hypothese sur la cause racine','5. Ecrire un test qui echoue (prouve le bug)','6. Corriger','7. Verifier que le test passe','8. Verifier qu aucune regression n est introduite','','## Regles','','- Ne pas masquer le probleme (try/catch silencieux)','- Ne pas corriger sans comprendre la cause','- Un fix sans test peut se regresser','- Si le bug touche la securite : suivre SECURITY_REVIEW.md','','## Commandes utiles','','  pnpm test -- --reporter=verbose','  pnpm typecheck','  supabase db test (si bug en base)'])
w('docs/ai/prompts/RELEASE_GO_NO_GO.md', ['# RELEASE_GO_NO_GO.md','','## Checklist Go/No-Go - Mise en production','','Voir aussi docs/security/PRODUCTION_SECURITY_GATE.md','','### Vote (GATE ABSOLUE)','- [ ] Protocole cryptographique valide','- [ ] Audit de securite independant realise','- [ ] Vulnerabilites critiques/elevees corrigees','','### Qualite','- [ ] Tous les tests passent (unit, integration, E2E, RLS)','- [ ] TypeScript zero erreur','- [ ] Lint propre','- [ ] Tests de charge realises','','### Infrastructure','- [ ] Sauvegardes automatiques configurees et testees','- [ ] Monitoring et alertes operationnels','- [ ] Procedure incident documentee','- [ ] Rollback planifie','','### Conformite','- [ ] Loi senegalaise 2008-12 examinee','- [ ] Formalites CDP accomplies','','### Approbation','- [ ] Approbation explicite de mise en production','- [ ] NEXT_PUBLIC_VOTE_MODE change de sandbox_non_production'])
w('docs/ai/prompts/CONTEXT_COMPACTION.md', ['# CONTEXT_COMPACTION.md','','## Pour reduire le contexte sans perdre l etat','','1. Mettre a jour STATUS.md avec l etat REEL du code','2. Mettre a jour NEXT_SESSION.md avec la prochaine action','3. Mettre a jour le sprint doc actif','4. Lister les fichiers modifies dans la session','5. Committer les changements stables','','## Ce qu il faut conserver','','- Decisions prises (ADR)','- Etat reel du code (pas une promesse)','- Tests passes et failes','- Prochaine action concrete','','## Ce qu on peut abandonner','','- Le detail des conversations','- Les explorations qui n ont pas abouti','- Les logs intermediaires','','## Format de transmission minimal','','  Lire : AGENTS.md + STATUS.md + NEXT_SESSION.md + SPRINT-XX.md','  Etat : [liste des fichiers cles modifies]','  Prochaine action : [une phrase concrete]'])
w('docs/ai/prompts/AGENT_HANDOFF.md', ['# AGENT_HANDOFF.md','','## Pour transmettre a un autre agent','','Le nouvel agent n a pas acces a l historique de conversation.','Il doit pouvoir demarrer uniquement depuis le depot.','','## Fichiers minimum a lire','','1. AGENTS.md','2. STATUS.md','3. NEXT_SESSION.md','4. docs/roadmap/sprints/<sprint_actif>.md','','## Message de transmission type','','  Projet : Plateforme SaaS de vote electronique','  Sprint actif : Sxx - <titre>','  Etat : voir STATUS.md (mis a jour)','  Prochaine action : voir NEXT_SESSION.md','  Stack : Next.js App Router + TypeScript + Supabase','','## Regles pour le nouvel agent','','- Lire AGENTS.md avant tout','- Ne pas reconstruire ce qui existe','- Ne pas changer la stack sans ADR','- Suivre les regles Git (pas de mention IA dans les commits)','- Gate vote : voir ADR-0006 et PRODUCTION_SECURITY_GATE.md'])
